# Client Class

class TeamsClient(ConnectorClientBase):
    """Typed client for teams connector."""

    def __init__(
        self,
        connection_runtime_url: str,
        token_provider: Optional[TokenProvider] = None,
        options: Optional[ConnectorClientOptions] = None,
    ):
        """
        Initialize a TeamsClient.

        Args:
            connection_runtime_url: The connection runtime
                URL from Azure Portal.
            token_provider: Optional token provider.
                Defaults to ManagedIdentityTokenProvider.
            options: Optional connector client options.
        """
        if not connection_runtime_url:
            raise ValueError("connection_runtime_url cannot be None or empty")

        if token_provider is None:
            token_provider = ManagedIdentityTokenProvider()

        super().__init__(token_provider, options)
        self._connection_runtime_url = connection_runtime_url.rstrip('/')

    @property
    def connector_name(self) -> str:
        return "teams"

    async def create_teams_meeting_async(
        self,
        input: NewMeeting,
        calendarid: str,
    ) -> dict[str, Any] | None:
        """
        Create a Teams meeting

        Create a meeting with a link at the bottom of the invite to join the
        meeting online on Microsoft Teams.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v1.0/me/calendars/{quote(str(calendarid), safe='')}/events"
        )

        response = await self.http_client.send_async(
            "POST", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

